useEffect(() => {
  setupForm();
  const fetchLocalizationTexts = async () => {
    try {
      await Promise.all(
        combinedLocales.map(async (locale) => {
          try {
            const response =
              (await adminClient.realms.getRealmLocalizationTexts({
                realm: realmName,
                selectedLocale: locale,
              })) as Record<string, string> | undefined;

            if (response) {
              setTableData([response]);
            }
